import{_ as a,o as e,c as i,a2 as s}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"세력과 외교","description":"","frontmatter":{},"headers":[],"relativePath":"world/Factions-and-Diplomacy.md","filePath":"world/Factions-and-Diplomacy.md"}'),d={name:"world/Factions-and-Diplomacy.md"};function l(n,t,r,h,o,p){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="세력과-외교" tabindex="-1">세력과 외교 <a class="header-anchor" href="#세력과-외교" aria-label="Permalink to &quot;세력과 외교&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-factions-diplomacy.svg?raw=true" alt="세력 협상과 통행권의 아이소 관계"></p><p>세력 간 협상과 통행권 부여를 위치·방향·시야 기반 관계로 결정합니다.</p><p>정치는 하나의 호감도가 아니라 개인 신뢰, 대중 평판, 지역별 정통성, 이행 가능한 약속과 집단 불만의 그래프입니다. 아래 수치는 <strong>설계 가정</strong>입니다.</p><h2 id="입력과-출력" tabindex="-1">입력과 출력 <a class="header-anchor" href="#입력과-출력" aria-label="Permalink to &quot;입력과 출력&quot;">​</a></h2><table tabindex="0"><thead><tr><th>입력</th><th style="text-align:right;">범위·기본값</th><th>출력</th></tr></thead><tbody><tr><td>신뢰 <code>T[A,B]</code></td><td style="text-align:right;">-100~100, 기본 0</td><td>개인·기관 간 협조</td></tr><tr><td>평판 <code>R[F,a]</code></td><td style="text-align:right;">-100~100, 기본 0</td><td>청중별 공개 평가</td></tr><tr><td>정통성 <code>L[F,n,k]</code></td><td style="text-align:right;">0~100, 현지 신규 주장 20</td><td>식량·전력·안전 등 근거별 승인</td></tr><tr><td>정치 자본 <code>PC</code></td><td style="text-align:right;">0~100, 기본 0</td><td>회의·보증·연합 행동 비용</td></tr><tr><td>불만 <code>G</code></td><td style="text-align:right;">0~100, 기본 0</td><td>청원·파업·봉쇄·분리 압력</td></tr><tr><td>결속 <code>C</code></td><td style="text-align:right;">0~100, 기본 0</td><td>집단 행동을 조직하는 능력</td></tr><tr><td>지렛대 <code>V</code></td><td style="text-align:right;">0~1, 기본 0</td><td>상대를 강제할 실질 수단</td></tr><tr><td>이행 신뢰도 <code>Rel</code></td><td style="text-align:right;">0~1</td><td>제안 수용과 계약 위험</td></tr></tbody></table><h2 id="계산-규칙" tabindex="-1">계산 규칙 <a class="header-anchor" href="#계산-규칙" aria-label="Permalink to &quot;계산 규칙&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rel = clamp(1 - 0.50*부족 - 0.30*고립 - 0.40*과확장, 0, 1)</span></span>
<span class="line"><span>신뢰변화 = clamp(sum(사건영향 * 신빙성), -25, 25)</span></span>
<span class="line"><span>T&#39; = clamp(T + 신뢰변화 + 기준선이동, -100, 100)</span></span>
<span class="line"><span>압력 = clamp(0.45*불만 + 0.35*결속 + 0.20*(100*지렛대), 0, 100)</span></span></code></pre></div><p>압력의 세 입력 중 불만과 결속은 0~100 척도이고, 지렛대는 0~1 척도라서 100을 곱해 같은 척도로 정규화한 뒤 가중합합니다. 압력은 0~100 값입니다.</p><p>모든 제안은 먼저 실제 경로, 물자, 권한, 배타 계약 충돌을 검사합니다. 불가능한 약속은 높은 교섭 능력으로 통과시킬 수 없습니다.</p><h2 id="기본-수치" tabindex="-1">기본 수치 <a class="header-anchor" href="#기본-수치" aria-label="Permalink to &quot;기본 수치&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th style="text-align:right;">기본값</th><th style="text-align:right;">최소</th><th style="text-align:right;">최대</th></tr></thead><tbody><tr><td>일반 회의 비용</td><td style="text-align:right;">5 정치 자본</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>긴급 심의 비용</td><td style="text-align:right;">10 정치 자본</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>연합 전체 안건</td><td style="text-align:right;">20 정치 자본</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>조직화 압력</td><td style="text-align:right;">40</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>위기 압력</td><td style="text-align:right;">70</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>강제 요구 지렛대</td><td style="text-align:right;">0.75</td><td style="text-align:right;">0</td><td style="text-align:right;">1</td></tr><tr><td>일반 협약 재검토</td><td style="text-align:right;">3주</td><td style="text-align:right;">1주</td><td style="text-align:right;">12주</td></tr></tbody></table><p>정치 자본 지출은 신뢰나 정통성을 직접 바꾸지 못하며, 그 값은 지출이 뒷받침한 행동의 기록된 결과로만 바뀝니다.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E[계약·구조·전투·부족 사건] --&gt; T[개인 신뢰]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E --&gt; R[청중별 평판]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E --&gt; L[근거별 정통성]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  T --&gt; P[제안 평가]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  R --&gt; P</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  L --&gt; P</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  P --&gt;|수락| C[협약과 의무]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  P --&gt;|거부| G[불만·연합 압력]</span></span></code></pre></div><h2 id="경계-상황" tabindex="-1">경계 상황 <a class="header-anchor" href="#경계-상황" aria-label="Permalink to &quot;경계 상황&quot;">​</a></h2><ul><li>관계 임계치는 신뢰 하나가 아니라 실행 가능성, 이익, 정통성과 협약 충돌을 함께 검사합니다.</li><li>압력 70 이상, 지렛대 0.75 이상이 2주 연속일 때만 파업·봉쇄·분리 같은 강제 요구가 열립니다.</li><li>고립은 외부 약속만 약화시키며 현지 통치의 정통성을 자동으로 깎지 않습니다.</li><li>후계자가 바뀌면 개인 약속과 제도 약속을 구분해 재검토합니다. 새 후계의 성명은 <a href="/world/Heirs-Names-and-World-Ledger.html">후계, 이름 로스터, 세계 원장</a>을 따릅니다.</li><li>동시 제안은 같은 주간 스냅샷으로 평가한 뒤 명령 ID 순서로 정산합니다.</li></ul><h2 id="계산-예시" tabindex="-1">계산 예시 <a class="header-anchor" href="#계산-예시" aria-label="Permalink to &quot;계산 예시&quot;">​</a></h2><p>부족 0.30, 고립 0.40, 과확장 0.50이면 감점은 각각 <code>0.50*0.30=0.15</code>, <code>0.30*0.40=0.12</code>, <code>0.40*0.50=0.20</code>이고 <code>Rel=clamp(1-0.15-0.12-0.20,0,1)=0.53</code>입니다. 불만 80, 결속 60, 지렛대 0.8이면 <code>압력=clamp(0.45*80+0.35*60+0.20*(100*0.8),0,100)=73</code>이므로, 지렛대 조건(0.75 이상)과 함께 2주 연속 유지되면 강제 요구가 열립니다. 신뢰 60이더라도 실제 배송 성공률이 53%라면 장기 전력 공급 협약은 거부되거나 담보·단계 이행 조건이 붙습니다. 실패 원인이 제3자의 봉쇄이고 사전 통보했다면 신빙성 계수로 신뢰 손실을 줄일 수 있습니다.</p>`,18)])])}const y=a(d,[["render",l]]);export{c as __pageData,y as default};
